insert into org.jornada (codigo, circulo, nome, dominio, classe, onda, objetivo, frequencia, automacao_nivel, automacao_motivo, raias) select codigo, circulo, nome, dominio, classe, onda, objetivo, frequencia, automacao_nivel, automacao_motivo, raias from jsonb_to_recordset($j$[{"codigo": "GO-10", "circulo": 9, "nome": "Apurar e publicar o relato anual de impacto", "dominio": "Dados, crises e relatos", "classe": "recomendada", "onda": 2, "objetivo": "Fazer que, a cada ano, os temas e os indicadores de impacto sejam escolhidos pela definição da Identidade; os dados sejam coletados no catálogo de dados e analisados com avanços e lacunas; e o relato seja redigido na voz do Ecossistema, validado com os dados e o risco jurídico, aprovado pelos sócios e publicado. A Identidade define o que conta como impacto; a Governança apura e publica.", "frequencia": "Anual", "automacao_nivel": "média", "automacao_motivo": "Propor temas, coletar, analisar, redigir e publicar são de agente e automação; decidir os temas e validar são de pessoa da Governança; aprovar é dos sócios.", "raias": ["Sócios", "Governança · pessoa", "Governança · agente", "Governança · automação"]}]$j$::jsonb) as x(codigo text, circulo smallint, nome text, dominio text, classe text, onda smallint, objetivo text, frequencia text, automacao_nivel text, automacao_motivo text, raias text[]);
